import{f as e,h as t,j as n,n as r}from"./chunks/shared.rYHlazZf.js";var i=JSON.parse(`{"title":"Rendimiento y trabajo acotado","description":"","frontmatter":{"title":"Rendimiento y trabajo acotado","docId":"developer.performance","translationKey":"developer.performance","locale":"es","audience":"developer","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"04bc0a89b86724872adae3ab8ddc8e29f5517dad14d51bc103d917582cf289ae","translationRevision":"21aeade6188e21e4f81184f14fff6e80f9ae9c189ce3003f24d1e57e236bcf96","order":110},"headers":[],"relativePath":"es/developer/performance.md","filePath":"es/developer/performance.md","lastUpdated":1795727787000}`),a={name:`es/developer/performance.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="performance-and-bounded-work" tabindex="-1">Rendimiento y trabajo acotado <a class="header-anchor" href="#performance-and-bounded-work" aria-label="Permalink to “Rendimiento y trabajo acotado”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Objetivo y requisitos”">​</a></h2><p>Mide un cuello de botella concreto conservando contabilidad y cierre correcto. Parte de una compilación fija, entrada determinista y perfil aislado. Lee <a href="./events.html">eventos</a> para no confundir un feed más rápido con persistencia más fiable. Los números históricos pertenecen a su compilación y equipo; no son garantías actuales.</p><h2 id="measure-the-right-boundary" tabindex="-1">Medir el límite adecuado <a class="header-anchor" href="#measure-the-right-boundary" aria-label="Permalink to “Medir el límite adecuado”">​</a></h2><p>La bandeja del escritorio separa presentación descartable y respuestas fiables. Las instantáneas pueden combinarse; el desbordamiento fiable debe fallar visiblemente. Entrada LIVE, plugins, procesadores y automatizaciones tienen límites propios. Aumentar una cola puede trasladar presión de memoria o latencia a la siguiente etapa.</p><p>El runtime frontend expone diagnósticos agregados en desarrollo o al compilar con <code>VITE_TIKTOOLS_DIAGNOSTICS=1</code>. Incluyen filas renderizadas, percentiles de intervalos de cuadros, llamadas pendientes, imágenes y temporizadores propios. Una WebView puede no proporcionar memoria del montón JavaScript. La visibilidad de página y ventana determina el interés de presentación, sin detener la contabilidad de negocio.</p><h2 id="run-a-focused-comparison" tabindex="-1">Ejecutar una comparación dirigida <a class="header-anchor" href="#run-a-focused-comparison" aria-label="Permalink to “Ejecutar una comparación dirigida”">​</a></h2><ol><li>Registra revisión, plataforma, mezcla de eventos, imágenes activas, pestaña y duración.</li><li>Establece una referencia con la misma muestra y periodo de medición.</li><li>Cambia un límite y compara caudal, latencia p95/p99, descartes, huecos, memoria retenida y drenaje al cerrar.</li><li>Incluye un plugin o consumidor lento y una cola saturada; una medición en reposo no prueba contrapresión.</li></ol><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> live-feed-state</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tiktools-core</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --features</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> persistence,native-tiktok</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> live_throughput</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span></span></code></pre></div><p>Revisa las características requeridas antes de activar una prueba nativa de rendimiento; las unidades dirigidas no necesitan una conexión TikTok real. Consulta <code>crates/tiktools-core/tests/live_throughput.rs</code> y las pruebas de la bandeja del escritorio.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado y estado <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to “Resultado esperado y estado”">​</a></h2><p>Las rutas acotadas implementan contadores y avisos de huecos. El <a href="https://github.com/nglmercer/TikTools-app/blob/remake/crates/tiktools-core/src/services/points/queue.rs" target="_blank" rel="noreferrer">escritor ordenado actual</a> rechaza escrituras saturadas antes de modificar memoria y prohíbe escribir síncronamente como alternativa. Los informes antiguos describen defectos de orden ya superados. Evalúa caché y recuperación con código/pruebas actuales; memoria visual acotada no demuestra corrección completa.</p><h2 id="recover" tabindex="-1">Recuperación <a class="header-anchor" href="#recover" aria-label="Permalink to “Recuperación”">​</a></h2><p>Si mejoran los cuadros y empeora la salud contable, revierte el cambio del límite e inspecciona admisión y escritura. Si crecen los temporizadores en pestañas ocultas, revisa la <a href="./lifecycle.html">liberación</a>. Conserva cantidades de entrada, aceptadas y pérdidas clasificadas. Un hueco puede recuperar la vista, pero no reparar efectos rechazados o inciertos.</p>`,14)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};